+      margin: 0;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 700;
+      transition: transform 160ms ease, background 160ms ease, box-shadow 160ms ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 3px solid rgba(255, 255, 255, 0.42);
+      outline-offset: 3px;
+    }
+
+    .trigger {
+      flex: 0 0 auto;
+      padding: 13px 20px;
+      color: white;
+      background: linear-gradient(135deg, var(--danger), var(--danger-dark));
+      box-shadow: 0 12px 30px rgba(255, 77, 109, 0.25);
+    }
+
+    .modal-overlay {
+      position: fixed;
+      inset: 0;
+      display: none;
+      place-items: center;
+      padding: 24px;
+      background: rgba(3, 7, 18, 0.72);
+      backdrop-filter: blur(10px);
+    }
+
+    .modal-overlay.is-open {
+      display: grid;
+    }
+
+    .modal {
+      width: min(100%, 460px);
+      padding: 28px;
+      border: 1px solid var(--border);
+      border-radius: 24px;
+      background: linear-gradient(180deg, var(--panel-strong), var(--panel));
+      box-shadow: var(--shadow);
+    }
+
+    .modal-icon {
+      width: 52px;
+      height: 52px;
+      display: grid;
+      place-items: center;
+      margin-bottom: 18px;
+      border-radius: 18px;
+      color: #ffd7df;
+      background: rgba(255, 77, 109, 0.14);
+      font-size: 1.6rem;
+    }
+
+    .modal h2 {
+      margin: 0 0 10px;
+      font-size: 1.55rem;
+      letter-spacing: -0.03em;
+    }
+
+    .modal-actions {
+      display: flex;
+      justify-content: flex-end;
+      gap: 12px;
+      margin-top: 26px;
+    }
+
+    .button-secondary,
+    .button-danger {
+      padding: 12px 18px;
+    }
+
+    .button-secondary {
+      color: var(--text);
+      background: rgba(255, 255, 255, 0.09);
+    }
+
+    .button-secondary:hover {
+      background: rgba(255, 255, 255, 0.14);
+    }
+
+    .button-danger {
+      color: white;
+      background: var(--danger);
+      box-shadow: 0 12px 24px rgba(255, 77, 109, 0.22);
+    }
+
+    .button-danger:hover {
+      background: var(--danger-dark);
+    }
+
+    @media (max-width: 620px) {
+      body {
+        padding: 18px;
+      }
+
+      .preview-details,
+      .modal-actions {
+        align-items: stretch;
+        flex-direction: column;
+      }
+
+      .trigger,
+      .modal-actions button {
+        width: 100%;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="preview-card">
+    <div class="image-frame">
+      <img src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80" alt="A sunlit cabin beside a calm lake">
+    </div>
+
+    <section class="preview-details" aria-labelledby="image-title">
+      <div>
+        <h1 id="image-title">Lakeside cabin</h1>
+        <p>Saved to your library. Review the image before making changes.</p>
+      </div>
+      <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
+        Delete image
+      </button>
+    </section>
+  </main>
+
+  <div class="modal-overlay" id="modal-overlay" aria-hidden="true">
+    <section class="modal" id="delete-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description">
+      <div class="modal-icon" aria-hidden="true">!</div>
+      <h2 id="dialog-title">Delete this image?</h2>
+      <p id="dialog-description">
+        This will remove the image from your library. This action cannot be undone.
+      </p>
+
+      <div class="modal-actions">
+        <button class="button-secondary" type="button" data-close-modal>Cancel</button>
+        <button class="button-danger" type="button" data-confirm-delete>Delete permanently</button>
+      </div>
+    </section>
+  </div>
+
+  <script>
+    const trigger = document.querySelector(".trigger");
+    const overlay = document.querySelector("#modal-overlay");
+    const closeButton = document.querySelector("[data-close-modal]");
+    const confirmButton = document.querySelector("[data-confirm-delete]");
+
+    function openModal() {
+      overlay.classList.add("is-open");
+      overlay.setAttribute("aria-hidden", "false");
+      closeButton.focus();
+    }
+
+    function closeModal() {
+      overlay.classList.remove("is-open");
+      overlay.setAttribute("aria-hidden", "true");
+      trigger.focus();
+    }
+
+    trigger.addEventListener("click", openModal);
+    closeButton.addEventListener("click", closeModal);
+
+    confirmButton.addEventListener("click", () => {
+      closeModal();
+      trigger.textContent = "Image deleted";
+      trigger.disabled = true;
+    });
+
+    overlay.addEventListener("click", (event) => {
+      if (event.target === overlay) {
+        closeModal();
+      }
+    });
+
+    document.addEventListener("keydown", (event) => {
+      if (event.key === "Escape" && overlay.classList.contains("is-open")) {
+        closeModal();
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
